import React, { useState } from "react";
import { Box, Button, Grid, MenuItem, TextField } from "@mui/material";

import MasterService from "../../../services/MasterService";
import { useNotificationHandling } from "../../../Components/useNotificationHandling ";
import { MessageAlert } from "../../../Components/MessageAlert";
import { CustomLoader } from "../../../Components/CustomLoader";
import { useSelector } from "react-redux";
import {
  canCreateTransporter,
  canSetTransporterTypeOnCreate,
  canEditTransporterCapability,
} from "../../../utility/masterAccess";

const TRANSPORTER_TYPE_CHOICES = [
  "Surface Transport",
  "Courier",
  "Local-Adhoc",
];

const initialFormState = {
  transporter_name: "",
  transporter_type: "",
};

function MasterTransportCreate({ getTransportData, setOpenPopup }) {
  const [formData, setFormData] = useState(initialFormState);
  const [loading, setLoading] = useState(false);

  const { handleError, handleCloseSnackbar, alertInfo, handleSuccess } =
    useNotificationHandling();

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };
  const userData = useSelector((state) => state.auth.profile);
  const canCreate = canCreateTransporter(userData);
  const canEditType = canEditTransporterCapability(userData);
  const canSetType = canSetTransporterTypeOnCreate(userData);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!canCreate) {
      return;
    }

    try {
      setLoading(true);

      const payload = canSetType
        ? formData
        : { transporter_name: formData.transporter_name };

      await MasterService.createTransportMaster(payload);

      handleSuccess("Transport created successfully");

      setTimeout(() => {
        setOpenPopup(false);
        getTransportData();
      }, 1000);
    } catch (error) {
      handleError(error);
    } finally {
      setLoading(false);
    }
  };

  const handleReset = () => setFormData(initialFormState);

  return (
    <>
      <MessageAlert
        open={alertInfo.open}
        onClose={handleCloseSnackbar}
        severity={alertInfo.severity}
        message={alertInfo.message}
      />

      <CustomLoader open={loading} />

      <Box component="form" onSubmit={handleSubmit} sx={{ p: 1 }}>
        <Grid container spacing={2}>
          {/* Transporter Name */}
          <Grid item xs={12} sm={6}>
            <TextField
              fullWidth
              required
              label="Transporter Name"
              name="transporter_name"
              value={formData.transporter_name}
              onChange={handleChange}
              size="small"
            />
          </Grid>

          {/* Type / Capability is managed by Operations/Dispatch Manager or Admin. */}
          {canSetType && (
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                required
                select
                label="Transporter Type"
                name="transporter_type"
                value={formData.transporter_type}
                onChange={handleChange}
                size="small"
              >
                {TRANSPORTER_TYPE_CHOICES.map((type) => (
                  <MenuItem key={type} value={type}>
                    {type}
                  </MenuItem>
                ))}
              </TextField>
            </Grid>
          )}
        </Grid>

        {/* Action Buttons */}
        <Box
          sx={{
            display: "flex",
            justifyContent: "flex-end",
            gap: 1,
            mt: 3,
          }}
        >
          {canCreate && (
            <Button variant="outlined" color="error" onClick={handleReset}>
              Reset
            </Button>
          )}
          {canCreate && (
            <Button
              type="submit"
              variant="contained"
              color="success"
              disabled={loading}
            >
              Submit
            </Button>
          )}
        </Box>
      </Box>
    </>
  );
}

export default MasterTransportCreate;
